mapper.select:
select * from( select A.*, ROWNUM RN from( select ORG.ORG_NO ,ORG.NAME ,ORG.STATUS ,LEADER_MEM.MEMBER_NO as LEADER_NO ,LEADER_MEM.NICKNAME as LEADER_NICKNAME ,count(distinct CON.CONSULTANT_NO) as CONSULTANT_COUNT ,sum(CS_COUNT.STUDENT_COUNT) as STUDENT_COUNT from CONSULTANT_ORG ORG left join MEMBER LEADER_MEM on (LEADER_MEM.MEMBER_NO = ORG.LEADER_NO) left join CONSULTANT CON on (CON.ORG_NO = ORG.ORG_NO) left join ( select CONSULTANT_NO, count(*) as STUDENT_COUNT from CONSULTANT_STUDENT group by CONSULTANT_NO ) CS_COUNT on (CS_COUNT.CONSULTANT_NO = CON.CONSULTANT_NO)
and ORG.NAME like '%' || #{name} || '%' escape '/'
and ORG.STATUS = #{status}
and exists( select 1 from CONSULTANT CON2 left join MEMBER MEM2 on (CON2.CONSULTANT_NO = MEM2.MEMBER_NO) where ORG.ORG_NO = CON2.ORG_NO
and MEM2.NAME like '%' || #{consultantName} || '%' escape '/'
and MEM2.NICKNAME like '%' || #{consultantNickname} || '%' escape '/'
)
group by ORG.ORG_NO, ORG.NAME, ORG.STATUS, LEADER_MEM.MEMBER_NO, LEADER_MEM.NICKNAME order by ORG_NO desc ) A where ROWNUM <= #{endRow} ) B where RN >= #{startRow}

select count(*)


		from (
			select *
			from CONSULTANT_ORG
			where ORG_NO != #{orgNo}
		)


		from CONSULTANT_ORG


where NAME = #{name}

